"use client";

import React, { useState, useRef } from "react";
import type { ExtendedDictionaryItem } from "@/types/dictionary";
import { SearchBox } from "@/components/SearchBox";
import { KelimeKarti } from "@/components/KelimeKarti";
import { Header } from "@/components/Header";
import GununKelimesiKart from "@/components/GununKelimesiKart";

const AkilliKlavyeModule = require("@/components/AkilliKlavye");
const AkilliKlavye = AkilliKlavyeModule?.default ?? AkilliKlavyeModule;

interface SozlukEkraniProps {
  words: ExtendedDictionaryItem[];
  loading: boolean;
  totalCount: number;
}

export default function SozlukEkrani({
  words,
  loading,
  totalCount,
}: SozlukEkraniProps) {
  const [searchTerm, setSearchTerm] = useState<string>("");
  const [isKlavyeOpen, setIsKlavyeOpen] = useState<boolean>(false);
  const [fontSize, setFontSize] = useState<number>(16);
  const [karanlikMod, setKaranlikMod] = useState<boolean>(false);
  const [tema, setTema] = useState<"light" | "dark">("light");

  // AkilliKlavye için ref tanımlaması
  const inputRef = useRef<HTMLInputElement>(null);

  const handleLetterClick = (letter: string): void => {
    setSearchTerm((prev) => prev + letter);
  };

  const handleSelectWord = (item: ExtendedDictionaryItem): void => {
    if (typeof item.kelime === "string") {
      setSearchTerm(item.kelime);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-gray-100 pb-20">
      <Header
        tema={tema}
        metinBoyutu={fontSize}
        karanlikMod={karanlikMod}
        setMetinBoyutu={setFontSize}
        setKaranlikMod={setKaranlikMod}
        setTema={setTema}
      />

      <main className="max-w-4xl mx-auto px-4 py-6 space-y-6">
        <SearchBox
          searchTerm={searchTerm}
          setSearchTerm={setSearchTerm}
          onLetterClick={handleLetterClick}
          isKlavyeOpen={isKlavyeOpen}
          setIsKlavyeOpen={setIsKlavyeOpen}
        />

        {isKlavyeOpen && (
          <div
            id="akilli-klavye"
            role="region"
            aria-label="Çerkesçe Sanal Klavye"
            className="p-3 bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 shadow-lg"
          >
            <AkilliKlavye
              sorgu={searchTerm}
              setSorgu={setSearchTerm}
              karanlikMod={karanlikMod}
              inputRef={inputRef}
            />
          </div>
        )}

        <div className="flex justify-between items-center text-xs text-gray-500 dark:text-gray-400 px-1">
          <span>{loading ? "Sözlükler yükleniyor..." : "Sözlükler hazır"}</span>
          <span>
            {words.length.toLocaleString()} / {totalCount.toLocaleString()} kayıt
          </span>
        </div>

        {!searchTerm && (
          <GununKelimesiKart
            gununKelimesi={words[0] || null}
            metinBoyutu={fontSize}
            karanlikMod={karanlikMod}
            tema={tema}
            onSelect={handleSelectWord}
          />
        )}

        <div className="space-y-3">
          {words.map((item, index) => {
            const uniqueKey =
              typeof item.id === "string" || typeof item.id === "number"
                ? String(item.id)
                : `${item.kelime ?? "kelime"}-${index}`;

            return (
              <KelimeKarti
                key={uniqueKey}
                item={item}
                fontSize={fontSize}
                onSelect={handleSelectWord}
              />
            );
          })}
        </div>
      </main>
    </div>
  );
}