'use client';

import React, { memo } from 'react';
import type { Dispatch, RefObject, SetStateAction } from 'react';

export interface AkilliKlavyeProps {
  inputRef: RefObject<HTMLInputElement | null>;
  sorgu: string;
  setSorgu: Dispatch<SetStateAction<string>>;
  metinBoyutu?: number;
  karanlikMod?: boolean;
  onKeyClick?: (char: string) => void;
  onDelete?: () => void;
}

const CERKESCE_HARFLER = [
  'I', 'ӏ', 'Гъ', 'Дж', 'Дз', 'Къ', 'КӀ', 'ПӀ', 'ТӀ', 'Хь', 'Хъ', 'ЦӀ', 'ШӀ', 'ЩӀ'
];

export const AkilliKlavye = memo(function AkilliKlavye({
  inputRef,
  sorgu,
  setSorgu,
  metinBoyutu = 16,
  karanlikMod = false,
  onKeyClick,
  onDelete,
}: AkilliKlavyeProps) {
  const handleHarfEkle = (harf: string) => {
    setSorgu((prev: string) => prev + harf);
    onKeyClick?.(harf);
    inputRef.current?.focus();
  };

  const handleSil = () => {
    setSorgu((prev: string) => prev.slice(0, -1));
    onDelete?.();
    inputRef.current?.focus();
  };

  return (
    <div
      role="region"
      aria-label="Çerkesçe Özel Karakter Klavyesi"
      className={`flex flex-wrap gap-1.5 p-3 rounded-xl border transition-colors ${
        karanlikMod
          ? 'bg-slate-900 border-slate-800 text-slate-100'
          : 'bg-slate-50 border-slate-200 text-slate-800'
      }`}
      style={{ fontSize: `${metinBoyutu}px` }}
    >
      {CERKESCE_HARFLER.map((harf) => (
        <button
          key={harf}
          type="button"
          onClick={() => handleHarfEkle(harf)}
          className="px-3 py-2 rounded-lg bg-red-600 hover:bg-red-700 text-white font-semibold transition-all active:scale-95 focus:outline-none focus:ring-2 focus:ring-red-400 select-none"
        >
          {harf}
        </button>
      ))}
      <button
        type="button"
        onClick={handleSil}
        aria-label="Son karakteri sil"
        className="px-3 py-2 rounded-lg bg-slate-700 hover:bg-slate-800 text-white font-semibold transition-all active:scale-95 focus:outline-none focus:ring-2 focus:ring-slate-400 select-none ml-auto"
      >
        Sil ⌫
      </button>
    </div>
  );
});

export default AkilliKlavye;
