'use client';

import React, { memo } from 'react';
import type { RefObject, Dispatch, SetStateAction } from 'react';

export interface SearchBoxProps {
  // Tip tanımlamaları
  sorgu: string;
  setSorgu: React.Dispatch<React.SetStateAction<string>>;
}
export const SearchBox = memo(function SearchBox({ sorgu, setSorgu }: SearchBoxProps) {
  return (
    <div className="w-full max-w-3xl mx-auto">
      <input
        type="text"
        value={sorgu}
        onChange={(e) => setSorgu(e.target.value)}
        placeholder="Kelime ara..."
        className="w-full px-4 py-3 rounded-xl border border-slate-200 dark:border-slate-800"
      />
    </div>
  );
});
export interface AramaKutusuProps {
  inputRef: RefObject<HTMLInputElement | null>;
  sorgu: string;
  setSorgu: Dispatch<SetStateAction<string>>;
  metinBoyutu: number;
  setMetinBoyutu: Dispatch<SetStateAction<number>>;
  karanlikMod: boolean;
  setKaranlikMod: Dispatch<SetStateAction<boolean>>;
  toplamKayıt?: number;
  yuklenenSozlukSayisi?: number;
}

const CERKESCE_HARFLER = [
  'I', 'ӏ', 'А', 'Б', 'В', 'Г', 'Гу', 'Гъ', 'Гъу', 'Д', 'Дж', 'Дз', 'Къ', 'КӀ', 'ПӀ', 'ТӀ', 'Хь'
];

export const AramaKutusu = memo(function AramaKutusu({
  inputRef,
  sorgu,
  setSorgu,
  metinBoyutu,
  setMetinBoyutu,
  karanlikMod,
  setKaranlikMod,
  toplamKayıt = 428679,
  yuklenenSozlukSayisi = 34,
}: AramaKutusuProps) {
  const handleHarfEkle = (harf: string) => {
    setSorgu((prev: string) => prev + harf);
    inputRef.current?.focus();
  };

  const handleSil = () => {
    setSorgu((prev: string) => prev.slice(0, -1));
    inputRef.current?.focus();
  };

  return (
    <div className="w-full max-w-3xl mx-auto p-6 space-y-4 rounded-2xl bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 shadow-xl transition-all">
      {/* Üst Bar: Başlık ve Kontroller */}
      <div className="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-slate-800">
        <div>
          <h1 className="text-2xl font-extrabold bg-gradient-to-r from-red-600 to-amber-600 bg-clip-text text-transparent">
            Çerkesçe Sözlük
          </h1>
          <p className="text-xs text-slate-500 dark:text-slate-400 font-medium mt-0.5">
            {yuklenenSozlukSayisi} Sözlük Aktif • {toplamKayıt.toLocaleString('tr-TR')} Kayıt
          </p>
        </div>

        {/* Tipografi ve Tema Araçları */}
        <div className="flex items-center gap-2 bg-slate-100 dark:bg-slate-800 p-1.5 rounded-xl">
          <button
            type="button"
            onClick={() => setMetinBoyutu((prev) => Math.max(prev - 2, 12))}
            className="px-2 py-1 text-xs font-bold rounded-lg bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200 shadow-sm hover:bg-slate-50 dark:hover:bg-slate-600 transition"
            title="Metni Küçült"
          >
            A-
          </button>
          <span className="text-xs font-semibold text-slate-500 dark:text-slate-400 px-1">
            {metinBoyutu}px
          </span>
          <button
            type="button"
            onClick={() => setMetinBoyutu((prev) => Math.min(prev + 2, 24))}
            className="px-2 py-1 text-xs font-bold rounded-lg bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200 shadow-sm hover:bg-slate-50 dark:hover:bg-slate-600 transition"
            title="Metni Büyüt"
          >
            A+
          </button>
          <div className="w-px h-4 bg-slate-300 dark:bg-slate-700 mx-1" />
          <button
            type="button"
            onClick={() => setKaranlikMod(!karanlikMod)}
            className="p-1.5 rounded-lg bg-white dark:bg-slate-700 text-slate-700 dark:text-amber-400 shadow-sm hover:bg-slate-50 dark:hover:bg-slate-600 transition"
            aria-label="Tema Değiştir"
          >
            {karanlikMod ? '🌙' : '☀️'}
          </button>
        </div>
      </div>

      {/* Arama İnput Alanı */}
      <div className="relative flex items-center">
        <input
          ref={inputRef}
          type="text"
          value={sorgu}
          onChange={(e) => setSorgu(e.target.value)}
          placeholder="Kelime veya anlam ara..."
          style={{ fontSize: `${metinBoyutu}px` }}
          className="w-full pl-4 pr-12 py-3.5 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 text-slate-900 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-red-500/50 focus:border-red-500 transition-all shadow-inner"
        />
        <div className="absolute right-3 p-2 text-slate-400 hover:text-red-500 transition cursor-pointer">
          🔍
        </div>
      </div>

      {/* Akıllı Özel Karakter Klavyesi */}
      <div className="pt-2">
        <div className="flex items-center justify-between mb-2">
          <span className="text-xs font-semibold text-slate-400 dark:text-slate-500 uppercase tracking-wider">
            Çerkesçe Karakterler
          </span>
        </div>
        <div className="flex flex-wrap gap-1.5">
          {CERKESCE_HARFLER.map((harf) => (
            <button
              key={harf}
              type="button"
              onClick={() => handleHarfEkle(harf)}
              style={{ fontSize: `${Math.max(metinBoyutu - 2, 13)}px` }}
              className="px-3 py-1.5 rounded-lg bg-slate-100 hover:bg-red-600 dark:bg-slate-800 dark:hover:bg-red-600 text-slate-700 dark:text-slate-200 hover:text-white dark:hover:text-white font-medium border border-slate-200/60 dark:border-slate-700/60 transition-all active:scale-95 shadow-sm select-none"
            >
              {harf}
            </button>
          ))}
          <button
            type="button"
            onClick={handleSil}
            style={{ fontSize: `${Math.max(metinBoyutu - 2, 13)}px` }}
            className="ml-auto px-3.5 py-1.5 rounded-lg bg-red-50 dark:bg-red-950/40 text-red-600 dark:text-red-400 hover:bg-red-600 hover:text-white dark:hover:bg-red-600 dark:hover:text-white border border-red-200 dark:border-red-900/50 font-medium transition-all active:scale-95 shadow-sm select-none"
          >
            Sil ⌫
          </button>
        </div>
      </div>
    </div>
  );
});

export default AramaKutusu;